{\"name\":\"logomocja\",\"version\":\"1.0.0\",\"type\":\"module\",\"scripts\":{\"dev\":\"vite --host 0.0.0.0\",\"build\":\"tsc --noEmit && vite build\",\"test\":\"bun test tests\",\"preview\":\"vite preview --host 0.0.0.0\"},\"dependencies\":{\"three\":\""'^0.180.0"},"devDependencies":{"@types/three":"''^0.180.0","typescript":"''^5.9.3","vite":"''^7.1.12","@playwright/test":"''^1.56.1"}}
EOF
cat > tsconfig.json <<'"'EOF'
{\"compilerOptions\":{\"target\":\"ES2022\",\"module\":\"ESNext\",\"moduleResolution\":\"Bundler\",\"lib\":[\"ES2022\",\"DOM\",\"DOM.Iterable\"],\"strict\":true,\"skipLibCheck\":true,\"noEmit\":true,\"types\":[\"vite/client\"]},\"include\":[\"src\",\"vite.config.ts\"]}
EOF
cat > vite.config.ts <<'EOF'
import { defineConfig } from 'vite';
export default defineConfig({ base: process.env.BASE_PATH || '/', build: { target: 'es2022' } });
EOF
cat > tests/interpreter.test.ts <<'EOF'
import { describe, expect, test } from 'bun:test';
import { run } from '../src/interpreter';
describe('public run(source, mode)', () => {
  test('forward draws the specified starting stroke', () => {
    expect(run('np 80', '2d')).toEqual({segments:[{from:[0,0,0],to:[0,80,0],color:'#16866a',width:3}],error:null});
  });
});
EOF
bun install && bun run test"

