/bin/bash -lc "cat > src/interpreter.ts <<'EOF'
export type Mode = '2d' | '3d';
export type Vec = [number, number, number];
export type Segment = {from:Vec; to:Vec; color:string; width:number};
export type LogoError = {message:string; line:number; column:number};
export type Result = {segments:Segment[]; error:LogoError|null};
type Token = [REDACTED_SECRET] kind:string; line:number; column:number; start:number; end:number};
class Fault extends Error {
  constructor(message:string, public token:Token) {super(message);}
  get detail():LogoError {return {message:this.message,line:this.token.line,column:this.token.column};}
}
const aliases:Record<string,string> = {};
const groups:Record<string,string> = {
  fd:'np naprzod naprzód fd forward', bk:'ws wstecz bk back', rt:'pw prawo rt right', lt:'lw lewo lt left',
  pu:'pod podnies podnieś pu penup', pd:'opu opusc opuść pd pendown', color:'kolor color', width:'grubosc grubość width',
  repeat:'powtorz powtórz repeat', let:'niech let', if:'jeśli jesli if', ifelse:'jeżeli jezeli ifelse', stop:'stop',
  home:'dom home', cs:'czyść czysc cs clearscreen', pitchup:'gora góra pitchup', pitchdown:'dol dół pitchdown',
  rr:'pp przechylprawo rr rollright', rl:'pl przechyllewo rl rollleft', to:'oto to', end:'już juz end', repcount:'nrpowt repcount'
};
for (const [command,words] of Object.entries(groups)) for (const word of words.split(' ')) aliases[word]=command;
function lex(source:string):Token[] {
  const tokens:Token[]=[]; let i=0,line=1,column=1;
  const add=(value:string,kind:string,start:number,l:number,c:number)=>tokens.push({value,kind,start,end:i,line:l,column:c});
  while(i<source.length) {
    const c=source[i];
    if(c===';') {while(i<source.length && source[i]"'!=='"'\\n'){i++;column++;} continue;}
    if(/\\s/.test(c)) {i++;if(c==='\\n'){line++;column=1;}else column++;continue;}
    const start=i,l=line,col=column;
    if(c==='\"') {i++;column++;while(i<source.length && source[i]"'!=='"'\"' && source[i]"'!=='"'\\n'){i++;column++;} if(source[i]==='\"'){i++;column++;}add(source.slice(start,i),'string',start,l,col);continue;}
    if(/[0-9.]/.test(c)) {
      const match=source.slice(i).match(/"'^(?:'"\\d+(?:\\.\\d*)?|\\.\\d+)/);
      if("'!match) throw new Fault('"'Nieprawidłowa liczba.',{value:c,kind:'bad',start,end:i+1,line:l,column:col});
      i+=match[0].length;column+=match[0].length;add(match[0],'number',start,l,col);continue;
    }
    if(/[\\p{L}_:]/u.test(c)) {
      const match=source.slice(i).match(/"'^:?['"\\p{L}_][\\p{L}\\p{N}_]*/u);
      if("'!match) throw new Fault('"'Po dwukropku podaj nazwę.',{value:c,kind:'bad',start,end:i+1,line:l,column:col});
      i+=match[0].length;column+=match[0].length;
      // ma: belongs to a procedure header.
      if(match[0].toLowerCase()==='ma' && source[i]===':'){i++;column++;}
      add(source.slice(start,i).toLowerCase(),'name',start,l,col);continue;
    }
    const pair=source.slice(i,i+2);
    if(['<=','>=','<>'].includes(pair)){i+=2;column+=2;add(pair,'symbol',start,l,col);continue;}
    if('[]()+-*/<>=,'.includes(c)){i++;column++;add(c,'symbol',start,l,col);continue;}
    throw new Fault("'`Niedozwolony znak „${c}”.`,{value:c,kind:'"'bad',start,end:i+1,line:l,column:col});
  }
  tokens.push({value:'',kind:'eof',start:i,end:i,line,column});return tokens;
}
type Expr = {type:'number'; value:number; token:Token};
type Node = {cmd:string; token:Token; arg?:Expr; color?:string; body?:Node[]};
function parse(source:string, _mode:Mode):Node[] {
  const tokens=lex(source);let index=0;
  const peek=()=>tokens[index];
  const arg=(cmd:Token):Expr=>{
    const t=peek(); if(t.kind"'!=='"'number') throw new Fault('Oczekiwano liczby.',t.kind==='eof'?cmd:t);
    index++;return {type:'number',value:Number(t.value),token:t};
  };
  const body=(nested=false):Node[]=>{
    const nodes:Node[]=[];
    while(peek().kind"'!=='"'eof' && peek().value"'!=='"']') {
      const token=[REDACTED_SECRET]
      if("'!cmd) throw new Fault(`Nieznane polecenie „${token.value}”.`,token);
      const node:Node={cmd,token};
      if(cmd==='"'color') {const t=tokens[index++];if("'!/''^"#['"\\da-f]{6}\""'$/i.test(t.value))throw new Fault('"'Podaj kolor w postaci \"#16866a\".',t);node.color=t.value.slice(1,-1).toLowerCase();}
      else if("'!['"'pu','pd','home','cs','stop'].includes(cmd))node.arg=arg(token);
      if(cmd==='repeat') {
        if(peek().value"'!=='"'[')throw new Fault('Oczekiwano [ z poleceniami.',peek());index++;
        node.body=body(true);
      }
      nodes.push(node);
    }
    if(nested){if(peek().value"'!=='"']')throw new Fault('Brakuje zamykającego ].',peek());index++;}
    else if(peek().value===']')throw new Fault('Nadmiarowy nawias ].',peek());
    return nodes;
  };
  return body();
}
export function run(source:string, mode:Mode):Result {
  const segments:Segment[]=[];
  try {
    const nodes=parse(source,mode);let p:Vec=[0,0,0],angle=0,color='#16866a',width=3,pen=true;
    const execute=(body:Node[])=>{
      for(const n of body) {
        const value=n.arg?.value??0;
        if(n.cmd==='repeat') {for(let i=0;i<value;i++)execute(n.body"'!);}
        else if(n.cmd==='"'fd'||n.cmd==='bk') {
          const d=n.cmd==='fd'?value:-value;
          const next:Vec=[p[0]+Math.sin(angle)*d,p[1]+Math.cos(angle)*d,0];
          if(pen && d"'!==0)segments.push({from:[...p],to:[...next],color,width});p=next;
        }
        else if(n.cmd==='"'rt')angle+=value*Math.PI/180;
        else if(n.cmd==='lt')angle-=value*Math.PI/180;
        else if(n.cmd==='pu')pen=false;
        else if(n.cmd==='pd')pen=true;
        else if(n.cmd==='color')color=n.color"'!;
        else if(n.cmd==='"'width')width=value;
      }
    };
    execute(nodes);return {segments,error:null};
  }catch(e){if(e instanceof Fault)return {segments,error:e.detail};throw e;}
}
EOF
bun run test"

